result = 0.0

if contract.has_family_loads:
    segment = (contract.family_loads_segment or 'a').upper()
    if segment in ('A', 'B', 'C'):
        indicator = payslip.env['previred.indicator'].sudo().search(
            [('date', '<=', payslip.date_from)], order='date desc', limit=1)

        if indicator:
            valor_carga = 0.0
            if segment == 'A':
                valor_carga = indicator.tramo_a or 0.0
            elif segment == 'B':
                valor_carga = indicator.tramo_b or 0.0
            elif segment == 'C':
                valor_carga = indicator.tramo_c or 0.0

            cargas_totales = (
                (contract.family_simple_loads_count or 0)
                + 2 * (contract.family_invalid_loads_count or 0)
                + (contract.family_maternal_loads_count or 0)
            )

            if valor_carga > 0 and cargas_totales > 0:
                # Días con remuneración imponible (asistencia + vacaciones)
                asistencia_days = 0
                vac_days = 0
                for line in payslip.worked_days_line_ids:
                    code = line.work_entry_type_id.code or ""
                    if code == "WORK100":
                        asistencia_days += line.number_of_days or 0
                    elif code == "LEAVECL120":
                        vac_days += line.number_of_days or 0

                total_days = asistencia_days + vac_days
                if total_days > 30:
                    total_days = 30

                absent_days = sum(
                    l.number_of_days or 0
                    for l in payslip.worked_days_line_ids
                    if l.work_entry_type_id.code in ["LIC", "LEAVE90", "OUT"]
                )
                if total_days < 30:
                    total_days += (30 - (vac_days + asistencia_days + absent_days))

                # DFL N°150 art. 12: si total_days >= 25, asignación completa;
                # si < 25, prorrateo proporcional sobre base 30.
                if total_days >= 25:
                    result = valor_carga * cargas_totales
                else:
                    result = valor_carga * cargas_totales * total_days / 30.0

# Art. 50: 25% fijo sobre remuneraciones imponibles

# Gratificación Art. 50: 25% del imponible del mes,
# tope: 4.75 * IMM / 12, prorrateado por días WORK100.

result = 0.0

if contract and contract.has_gratification:
    # 1) Base imponible del mes (sin incluir esta misma regla)
    base_imponible = categories.get('IMP', 0.0)
    if not base_imponible:
        base_imponible = categories.get('GROSS', 0.0)

    # 2) Días trabajados para prorrateo del tope (WORK100 + LEAVECL120)
    wd_work = worked_days.get('WORK100')
    wd_vacation = worked_days.get('LEAVECL120')

    dias_trabajo = wd_work.number_of_days if wd_work else 0.0
    dias_vacaciones = wd_vacation.number_of_days if wd_vacation else 0.0

    dias = dias_trabajo + dias_vacaciones

    if dias < 0.0:
        dias = 0.0
    if dias > 30.0:
        dias = 30.0
    proporcion = dias / 30.0

    # 3) Gratificación teórica (25%)
    gratif = base_imponible * 0.25

    # 4) Rango del mes (sin imports)
    year = payslip.date_from.year
    month = payslip.date_from.month
    start = payslip.date_from.replace(day=1)
    if month == 12:
        end = payslip.date_from.replace(year=year + 1, month=1, day=1)
    else:
        end = payslip.date_from.replace(month=month + 1, day=1)

    indicator = payslip.env['previred.indicator'].sudo().search([
        ('date', '>=', start),
        ('date', '<', end),
    ], order='date desc', limit=1)

    # 5) IMM: probar campos posibles sin usar getattr/hasattr
    imm = 0.0
    if indicator:
        try:
            imm = float(indicator.ingreso_minimo_mensual or 0.0)
        except:
            try:
                imm = float(indicator.sueldo_minimo or 0.0)
            except:
                try:
                    imm = float(indicator.ingreso_minimo or 0.0)
                except:
                    try:
                        imm = float(indicator.trab_dependiente_independiente or 0.0)
                    except:
                        imm = 0.0

    # 6) Tope mensual prorrateado
    tope = 0.0
    if imm:
        tope = (imm * 4.75 / 12.0) * proporcion

    # 7) Resultado con tope
    if tope == 0.0 or gratif <= tope:
        result = gratif
    else:
        result = tope

