        ], order='date desc', limit=1)

        total_days = 0
        vac_days = 0
        asistencia_days = 0
        for line in payslip.worked_days_line_ids:
            code = line.work_entry_type_id.code or ""
            if code == "WORK100":
                asistencia_days += line.number_of_days or 0
            elif code == "LEAVECL120":
                vac_days += line.number_of_days or 0
        total_days = asistencia_days + vac_days

        if indicator:
            calc_type = contract.isapre_calc_type or ''
            valor_plan_pactado = 0.0

            if calc_type == 'uf':
                if contract.isapre_uf_valor and indicator.uf_value_on_month:
                    valor_plan_pactado = contract.isapre_uf_valor * indicator.uf_value_on_month

            elif calc_type == 'clp':
                if contract.isapre_plan_monto:
                    valor_plan_pactado = contract.isapre_plan_monto

            if total_days < 30:
                result = (valor_plan_pactado/30) * total_days - cotizacion_legal_7
            else:    
                # Calcular adicional si la cotización legal no cubre el plan pactado
                adicional = valor_plan_pactado - cotizacion_legal_7
                result = adicional if adicional > 0 else 0.0
    else:
        result = 0.0
else:
